// Concatenates every migration and seed file into db/bundle.sql, so the whole
// schema can be applied in one paste into the Supabase SQL editor.
// Run: npm run db:bundle
import { readFile, readdir, writeFile } from 'node:fs/promises';
import path from 'node:path';

const ROOT = path.resolve(import.meta.dirname, '../..');

async function sqlFiles(dir) {
  const names = (await readdir(path.join(ROOT, dir))).filter(f => f.endsWith('.sql')).sort();
  return names.map(n => path.join(dir, n));
}

const files = [...await sqlFiles('db/migrations'), ...await sqlFiles('db/seed')];
const parts = [`-- ${'='.repeat(74)}
-- F1 infographic — complete database setup
--
-- GENERATED by etl/scripts/gen-bundle.mjs — do not edit by hand.
-- Regenerate with: npm run db:bundle
--
-- Paste this whole file into the Supabase SQL editor and run it once.
-- Safe to re-run: every statement is idempotent.
--
-- Source files, in order:
${files.map(f => `--   ${f}`).join('\n')}
-- ${'='.repeat(74)}
`];

for (const f of files) {
  parts.push(`\n\n-- ${'─'.repeat(74)}\n-- ${f}\n-- ${'─'.repeat(74)}\n`);
  parts.push(await readFile(path.join(ROOT, f), 'utf8'));
}

// PostgREST caches the schema; new views are invisible until it reloads.
parts.push(`\n\n-- ${'─'.repeat(74)}
-- Make the new views visible to the REST API immediately.
-- ${'─'.repeat(74)}
notify pgrst, 'reload schema';
`);

const out = path.join(ROOT, 'db/bundle.sql');
await writeFile(out, parts.join(''));
const bytes = (await readFile(out)).length;
console.log(`db/bundle.sql — ${files.length} files, ${(bytes / 1024).toFixed(0)} KB`);
